return {["scripts/quests/abyssea/Altepa_Dominion_Op_11.lua"]={["Path"]="scripts/quests/abyssea/Altepa_Dominion_Op_11.lua",["SHA256"]="7558cc35a40d5de40d5f2fa81590f231b9a051f40c8e84d585193959320386c8",["Text"]="-----------------------------------\n-- Altepa - Dominion Op #11\n-----------------------------------\n-- !addquest 8 97\n-- Dominion Sergeant (Volker's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_11_ALTEPA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ALTEPA] =\n        {\n            ['Nannakola'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 570)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Altepa_Dominion_Op_12.lua"]={["Path"]="scripts/quests/abyssea/Altepa_Dominion_Op_12.lua",["SHA256"]="14dde8279b345667f900f00c88278136bf6e87c00c6fb53a6051537ef0ae323f",["Text"]="-----------------------------------\n-- Altepa - Dominion Op #12\n-----------------------------------\n-- !addquest 8 98\n-- Dominion Sergeant (Volker's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_12_ALTEPA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ALTEPA] =\n        {\n            ['Akrab'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 571)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Altepa_Dominion_Op_13.lua"]={["Path"]="scripts/quests/abyssea/Altepa_Dominion_Op_13.lua",["SHA256"]="de57e3f69bbfb457c1c19894d6bf5e2f9f598cfdf591672bfa36c1e3baa7e78a",["Text"]="-----------------------------------\n-- Altepa - Dominion Op #13\n-----------------------------------\n-- !addquest 8 99\n-- Dominion Sergeant (Nanaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_13_ALTEPA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ALTEPA] =\n        {\n            ['Fear_Dearg'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 572)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Altepa_Dominion_Op_14.lua"]={["Path"]="scripts/quests/abyssea/Altepa_Dominion_Op_14.lua",["SHA256"]="11912ad3e2952c92df7cc6766707a907dbf876c3f7e675fc823731423722f5bd",["Text"]="-----------------------------------\n-- Altepa - Dominion Op #14\n-----------------------------------\n-- !addquest 8 100\n-- Dominion Sergeant (Nanaa Mihgo's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_14_ALTEPA)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_ALTEPA] =\n        {\n            ['Barrens_Treant'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 573)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/An_Eye_for_Revenge.lua"]={["Path"]="scripts/quests/abyssea/An_Eye_for_Revenge.lua",["SHA256"]="e469f92f411a774cdf656f9209416bf0d71fe8d359f9702b4825910230237538",["Text"]="-----------------------------------\n-- An Eye for Revenge\n-----------------------------------\n-- !addquest 8 3\n-- Curilla : !pos: -467.7 -3.5 -769.5 132\n-----------------------------------\nlocal ID = zones[xi.zone.ABYSSEA_LA_THEINE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.AN_EYE_FOR_REVENGE)\n\nquest.reward = {\n    keyItem     = xi.keyItem.SCARLET_ABYSSITE_OF_FURTHERANCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.LOST_MEMORIES) ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(189)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.LOST_MEMORIES) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    player:delKeyItem(xi.keyItem.VIAL_OF_LAMBENT_POTION)\n                    return quest:event(190)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [190] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.LUGARHOOS_EYEBALL) then\n                        return quest:event(191)\n                    else\n                        return quest:event(192)\n                    end\n                end,\n            },\n\n            ['Lugarhoo'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if not player:hasKeyItem(xi.keyItem.LUGARHOOS_EYEBALL) then\n                        player:addKeyItem(xi.keyItem.LUGARHOOS_EYEBALL)\n                        player:messageSpecial(ID.text.KEYITEM_OBTAINED, xi.keyItem.LUGARHOOS_EYEBALL)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [192] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.LUGARHOOS_EYEBALL)\n                    player:addCurrency('cruor', 800)\n                    player:messageSpecial(ID.text.CRUOR_TOTAL, 800, player:getCurrency('cruor'))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Curilla'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(193)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/An_Officer_and_a_Pirate.lua"]={["Path"]="scripts/quests/abyssea/An_Officer_and_a_Pirate.lua",["SHA256"]="4f71502f7f68c8701f644e897d93c6f7577ac59f6d1aa210ea126f9d15d3a4e9",["Text"]="-----------------------------------\n-- An Officer and a Pirate\n-----------------------------------\n-- !addquest 8 168\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of First Contact.\n-- Flags Heart of Madness upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.AN_OFFICER_AND_A_PIRATE)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(334)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [334] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.HEART_OF_MADNESS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/An_Ulcerous_Uragnite.lua"]={["Path"]="scripts/quests/abyssea/An_Ulcerous_Uragnite.lua",["SHA256"]="8bbdaf7a0ea667e1555fc8b51f5d48e5657f21c2feb1d0987c97fc5352558125",["Text"]="-----------------------------------\n-- An Ulcerous Uragnite\n-----------------------------------\n-- !addquest 8 178\n-- Cavernous Maw    : !pos -78.000 -0.500 600.000 106\n-- Amphitrite       : !spawnmob 17818054\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.abyssea.getHeldTraverserStones(player) >= 1 and\n                player:getQuestStatus(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Cavernous_Maw_2'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(0)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and player:hasTitle(xi.title.AMPHITRITE_SHUCKER)\n        end,\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 1\n            end,\n\n            onEventUpdate =\n            {\n                [1] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:updateEvent(xi.abyssea.getZoneKIReward(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.abyssea.getZoneKIReward(player))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Beneath_a_Blood_Red_Sky.lua"]={["Path"]="scripts/quests/abyssea/Beneath_a_Blood_Red_Sky.lua",["SHA256"]="08190f58b3b885c80c4dc4b24dffd18e71647e971f92efd539dec1bb06ee9b8c",["Text"]="-----------------------------------\n-- Beneath a Blood Red Sky\n-----------------------------------\n-- !addquest 8 183\n-- Transcendental Radiance : !pos -259.433 -21.581 220.498 126\n-- Flagged on completion of Emissaries of God.\n-- Zone into Abyssea - Empyreal Paradox. Flag The Wyrm God upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.BENEATH_A_BLOOD_RED_SKY)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_EMPYREAL_PARADOX] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 202\n            end,\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.THE_WYRM_GOD)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Champions_of_Abyssea.lua"]={["Path"]="scripts/quests/abyssea/Champions_of_Abyssea.lua",["SHA256"]="0cf6e2470901486c55db4aaaf8400adedd70ba2d28aa951e499056f281e95adb",["Text"]="-----------------------------------\n-- Champions of Abyssea\n-----------------------------------\n-- !addquest 8 171\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of Tenuous Existence.\n-- Complete when any 7 of the 9 zone quests are completed and player talks to Joachim. Flags A Sea Dog's Summons upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.CHAMPIONS_OF_ABYSSEA)\n\nquest.reward = {}\n\nlocal zoneQuests =\n{\n    xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS,\n    xi.quest.id.abyssea.TO_PASTE_A_PEISTE,\n    xi.quest.id.abyssea.MEGADRILE_MENACE,\n    xi.quest.id.abyssea.THE_BEAST_OF_BASTORE,\n    xi.quest.id.abyssea.A_DELECTABLE_DEMON,\n    xi.quest.id.abyssea.A_FLUTTERY_FIEND,\n    xi.quest.id.abyssea.A_BEAKED_BLUSTERER,\n    xi.quest.id.abyssea.A_MAN_EATING_MITE,\n    xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE,\n}\n\nlocal function countCompletedZoneQuests(player)\n    local count = 0\n    for _, questId in ipairs(zoneQuests) do\n        if player:hasCompletedQuest(xi.questLog.ABYSSEA, questId) then\n            count = count + 1\n        end\n    end\n\n    return count\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and countCompletedZoneQuests(player) >= 7\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(342)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [342] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.A_SEA_DOGS_SUMMONS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Dawn_of_Death.lua"]={["Path"]="scripts/quests/abyssea/Dawn_of_Death.lua",["SHA256"]="a7091a48e287e78cedb0d6b4a694b988656d0bbc81cc8ad7645661f5c71c137e",["Text"]="-----------------------------------\n-- Dawn of Death\n-----------------------------------\n-- !addquest 8 162\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of The Truth Beckons.\n-- Complete when any 3 of the 9 zone quests are completed and player talks to Joachim. Flags First Contact upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DAWN_OF_DEATH)\n\nquest.reward = {}\n\nlocal zoneQuests =\n{\n    xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS,\n    xi.quest.id.abyssea.TO_PASTE_A_PEISTE,\n    xi.quest.id.abyssea.MEGADRILE_MENACE,\n    xi.quest.id.abyssea.THE_BEAST_OF_BASTORE,\n    xi.quest.id.abyssea.A_DELECTABLE_DEMON,\n    xi.quest.id.abyssea.A_FLUTTERY_FIEND,\n    xi.quest.id.abyssea.A_BEAKED_BLUSTERER,\n    xi.quest.id.abyssea.A_MAN_EATING_MITE,\n    xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE,\n}\n\nlocal function countCompletedZoneQuests(player)\n    local count = 0\n    for _, questId in ipairs(zoneQuests) do\n        if player:hasCompletedQuest(xi.questLog.ABYSSEA, questId) then\n            count = count + 1\n        end\n    end\n\n    return count\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and countCompletedZoneQuests(player) >= 3\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(333)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [333] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.FIRST_CONTACT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Death_and_Rebirth.lua"]={["Path"]="scripts/quests/abyssea/Death_and_Rebirth.lua",["SHA256"]="986531996c38052e1a4a30c626671d8601d5a1c9704e38cc80afa3aff546e0f7",["Text"]="-----------------------------------\n-- Death and Rebirth\n-----------------------------------\n-- !addquest 8 181\n-- Joachim : !pos -52.844 0 -9.978 246\n-- Flagged on completion of A Sea Dog's Summons.\n-- Complete all 9 zone quests, then talk to Joachim. Zone into the Hall of the Gods between 18:00 and 5:00. Flags Emissaries of God upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DEATH_AND_REBIRTH)\n\nquest.reward = {}\n\nlocal zoneQuests =\n{\n    xi.quest.id.abyssea.A_GOLDSTRUCK_GIGAS,\n    xi.quest.id.abyssea.TO_PASTE_A_PEISTE,\n    xi.quest.id.abyssea.MEGADRILE_MENACE,\n    xi.quest.id.abyssea.THE_BEAST_OF_BASTORE,\n    xi.quest.id.abyssea.A_DELECTABLE_DEMON,\n    xi.quest.id.abyssea.A_FLUTTERY_FIEND,\n    xi.quest.id.abyssea.A_BEAKED_BLUSTERER,\n    xi.quest.id.abyssea.A_MAN_EATING_MITE,\n    xi.quest.id.abyssea.AN_ULCEROUS_URAGNITE,\n}\n\nlocal function allZoneQuestsComplete(player)\n    for _, questId in ipairs(zoneQuests) do\n        if not player:hasCompletedQuest(xi.questLog.ABYSSEA, questId) then\n            return false\n        end\n    end\n\n    return true\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and allZoneQuestsComplete(player)\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(343)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [343] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and quest:getVar(player, 'Prog') == 1\n        end,\n\n        [xi.zone.HALL_OF_THE_GODS] =\n        {\n            onZoneIn = function(player, prevZone)\n                local hour = VanadielHour()\n                if hour >= 18 or hour < 5 then\n                    return 7\n                end\n            end,\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.EMISSARIES_OF_GOD)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Emissaries_of_God.lua"]={["Path"]="scripts/quests/abyssea/Emissaries_of_God.lua",["SHA256"]="3a54aac87b637ed0b523bc659a2551874dc612e7c05261b482a053ef9d41328d",["Text"]="-----------------------------------\n-- Emissaries of God\n-----------------------------------\n-- !addquest 8 182\n-- Joachim      : !pos -52.844 0 -9.978 246\n-- Caturae NMs  :\n--   Iratham  (Abyssea - Tahrongi)  : !spawnmob 16961945\n--   Kutharei (Abyssea - Misareaux) : !spawnmob 17662497\n--   Sippoy   (Abyssea - Vunkerl)   : !spawnmob 17666511\n--   Yaanei   (Abyssea - Attohwa)   : !spawnmob 17658292\n--   Rani     (Abyssea - Altepa)    : !spawnmob 17670551\n--   Raja     (Abyssea - Grauberg)  : !spawnmob 17818051\n-- Flagged on completion of Death and Rebirth.\n-- Obtain all 6 caturae titles, then talk to Joachim for CS and Abyssite of Discernment. Zone into the Hall of the Gods between 18:00 and 5:00. Flags Beneath a Blood-red Sky upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.EMISSARIES_OF_GOD)\n\nquest.reward = {} -- Key item given in first cutscene, not on quest complete\n\nlocal caturaeTitles =\n{\n    xi.title.IRATHAM_CAPTURER,\n    xi.title.KUTHAREI_UNHORSER,\n    xi.title.SIPPOY_CAPTURER,\n    xi.title.YAANEI_CRASHER,\n    xi.title.RANI_DECROWNER,\n    xi.title.RAJA_REGICIDE,\n}\n\nlocal function hasAllCaturaeTitles(player)\n    for _, titleId in ipairs(caturaeTitles) do\n        if not player:hasTitle(titleId) then\n            return false\n        end\n    end\n\n    return true\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and hasAllCaturaeTitles(player)\n        end,\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Joachim'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(344)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [344] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ABYSSITE_OF_DISCERNMENT)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and quest:getVar(player, 'Prog') == 1\n        end,\n\n        [xi.zone.HALL_OF_THE_GODS] =\n        {\n            onZoneIn = function(player, prevZone)\n                local hour = VanadielHour()\n                if hour >= 18 or hour < 5 then\n                    return 8\n                end\n            end,\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.BENEATH_A_BLOOD_RED_SKY)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Fear_of_the_Dark_III.lua"]={["Path"]="scripts/quests/abyssea/Fear_of_the_Dark_III.lua",["SHA256"]="640001cdc624503423a9dd494e50406310ede25dd3a1115cd6d1614c713a4906",["Text"]="-----------------------------------\n-- Fear of the Dark III\n-----------------------------------\n-- !addquest 8 2\n-- Secodiand : !pos -489.5 -2.8 759.2 132\n-----------------------------------\nlocal ID = zones[xi.zone.ABYSSEA_LA_THEINE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.FEAR_OF_THE_DARK_III)\n\nquest.reward = {\n    fame     = 10,\n    fameArea = xi.fameArea.ABYSSEA_LATHEINE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Secodiand'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(161)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [161] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.ABYSSEA_LA_THEINE] =\n        {\n            ['Secodiand'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(159)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHas(trade, { { xi.item.CLIONID_WING, 3 } }) then\n                        return quest:event(160)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [160] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:addCurrency('cruor', 200)\n                    player:messageSpecial(ID.text.CRUOR_TOTAL, 200, player:getCurrency('cruor'))\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/First_Contact.lua"]={["Path"]="scripts/quests/abyssea/First_Contact.lua",["SHA256"]="e4ddc3ed6485c6b6c96f56b98fac1078a73639569f8108dcf6379437826445e1",["Text"]="-----------------------------------\n-- First Contact\n-----------------------------------\n-- !addquest 8 167\n-- qm3 : !pos -179 8 254 102\n-- Flagged on completion of Dawn of Death.\n-- Click ??? in La Theine Plateau between 18:00 and 5:00. Flags An Officer and a Pirate upon completion.\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.FIRST_CONTACT)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                VanadielHour() >= 18 and\n                VanadielHour() < 5\n        end,\n\n        [xi.zone.LA_THEINE_PLATEAU] =\n        {\n            ['qm3'] = quest:progressEvent(11),\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.ABYSSEA, xi.quest.id.abyssea.AN_OFFICER_AND_A_PIRATE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Grauberg_Dominion_Op_01.lua"]={["Path"]="scripts/quests/abyssea/Grauberg_Dominion_Op_01.lua",["SHA256"]="c800d7a8c6a2f6bab58864c64ed7de341f68d91d08fda0df0329fb0561fc49c6",["Text"]="-----------------------------------\n-- Grauberg - Dominion Op #01\n-----------------------------------\n-- !addquest 8 115\n-- Dominion Sergeant (Wolfgang's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_01_GRAUBERG)\n\nquest.reward = {}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.ABYSSEA_GRAUBERG] =\n        {\n            ['Sinister_Seidel'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    xi.abyssea.dominionOnMobDeath(mob, player, 588)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/abyssea/Grauberg_Dominion_Op_02.lua"]={["Path"]="scripts/quests/abyssea/Grauberg_Dominion_Op_02.lua",["SHA256"]="205b2a45651932325a3db6e922d3e89ba197f7fef6bbfca7cec64f3563514d35",["Text"]="-----------------------------------\n-- Grauberg - Dominion Op #02\n-----------------------------------\n-- !addquest 8 116\n-- Dominion Sergeant (Wolfgang's Camp)\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.ABYSSEA, xi.quest.id.abyssea.DOMINION_OP_02_GRAUBERG)\n\